def normalize(values):
    """Scale values linearly to [0, 1]: the minimum becomes 0.0, the maximum 1.0.

    If all values are equal, return a list of 0.0.
    An empty input returns an empty list.
    """
    if len(values) == 0:
        return []
    lo, hi = min(values), max(values)
    if len(values) == 0:
        return []
    if lo == hi:
        return [0.0] * len(values)
    return [(v - lo) / (hi - lo) for v in values]

from normalize import normalize


def test_basic():
    assert normalize([0, 5, 10]) == [0.0, 0.5, 1.0]


def test_negative_values():
    assert normalize([-10, 0, 10]) == [0.0, 0.5, 1.0]


def test_all_equal():
    assert normalize([5, 5, 5]) == [0.0, 0.0, 0.0]


def test_single_value():
    assert normalize([42]) == [0.0]


def test_empty():
    assert normalize([]) == []

def normalize(values):
    """Scale values linearly to [0, 1]: the minimum becomes 0.0, the maximum 1.0.

    If all values are equal, return a list of 0.0.
    An empty input returns an empty list.
    """
    if len(values) == 0:
        return []
    lo, hi = min(values), max(values)
    if len(values) == 0:
        return []
    if lo == hi:
        return [0.0] * len(values)
    return [(v - lo) / (hi - lo) for v in values]
